//! Strict fixed auxiliary evidence; no implicit absent/default observation.
use super::{QueryReply,QueryRequest,SourceQuery};use std::{io,path::Path};
fn invalid()->io::Error{io::Error::new(io::ErrorKind::InvalidData,"invalid captured DeadlinePolling auxiliary evidence")}
pub(super) fn reads_policy(query:&SourceQuery)->bool{matches!(query,SourceQuery::NativeDeadlinePollingEvidence{..})}
pub(super) fn validate_request(request:&QueryRequest)->io::Result<()>{for query in &request.source_queries{if let SourceQuery::NativeDeadlinePollingEvidence{root,configuration}=query{if !root.is_absolute()||!configuration.is_absolute()||request.expected_policy_revision.is_none(){return Err(invalid())}}}Ok(())}
pub(super) fn validate_requested(reply:&QueryReply,questions:&[SourceQuery])->io::Result<()>{if reply.jsonl.len()>super::MAX_OUTPUT{return Err(invalid())}let mut expected=questions.iter().filter_map(|q|if let SourceQuery::NativeDeadlinePollingEvidence{root,configuration}=q{Some((root,configuration))}else{None});for line in reply.jsonl.lines(){let row:serde_json::Value=serde_json::from_str(line).map_err(io::Error::other)?;if row["row"]!="source_native_deadline_evidence"{continue}let(root,configuration)=expected.next().ok_or_else(invalid)?;let names=["row","schema","source_revision","policy_revision","semantic_revision","snapshot_as_of","root","configuration","path","question","observation","text"];let object=row.as_object().ok_or_else(invalid)?;if object.len()!=names.len()||names.iter().any(|name|!object.contains_key(*name))||row["schema"]!="dm-session-source-query-v1"||row["source_revision"].as_str()!=reply.source_revision.as_deref()||reply.source_revision.is_none()||row["policy_revision"].as_str()!=reply.policy_revision.as_deref()||reply.policy_revision.is_none()||row["semantic_revision"].as_str()!=Some(reply.revision.as_str())||row["snapshot_as_of"]!="policy_revision"||row["question"]!="deadline_polling_allowlist"||row["root"]!=serde_json::to_value(root).map_err(io::Error::other)?||row["configuration"]!=serde_json::to_value(configuration).map_err(io::Error::other)?{return Err(invalid())}let path: &str=row["path"].as_str().ok_or_else(invalid)?;if Path::new(path).strip_prefix(root).ok()!=Some(Path::new("tools/ci/deadline_polling_allowlist.txt")){return Err(invalid())}match row["observation"].as_str(){Some("captured_utf8")if row["text"].is_string()=>{},Some("proven_missing"|"captured_non_utf8")if row["text"].is_null()=>{},_=>return Err(invalid())}}if expected.next().is_some(){return Err(invalid())}Ok(())}
